// Determine which sources to fetch from
const sources = ['remoteok', 'weworkremotely', 'remotive', 'arbeitnow'];
return sources.map(s => ({ json: { source: s } }));

// Normalize RemoteOK jobs
const items = $input.all();
const rawJobs = items[0].json;
if (!Array.isArray(rawJobs)) return [];

const roleKeywords = ['devops', 'devsecops', 'backend', 'cloud', 'platform', 'infrastructure', 'sre', 'site reliability', 'engineer', 'developer', 'fullstack', 'full-stack'];

const normalized = [];
for (const job of rawJobs) {
  if (!job.company || !job.position) continue; // skip legal notice first entry

  const title = (job.position || '').toLowerCase();
  const isRelevant = roleKeywords.some(k => title.includes(k));
  if (!isRelevant) continue;

  const description = [
    job.description || '',
    (job.tags || []).join(', ')
  ].join(' ').substring(0, 6000);

  normalized.push({
    json: {
      source: 'remoteok',
      source_job_id: String(job.id || job.slug || ''),
      company: job.company || 'Unknown',
      title: job.position || '',
      location: 'Remote',
      remote: true,
      employment_type: 'full-time',
      url: job.url || `https://remoteok.com/remote-jobs/${job.slug}`,
      description: description,
      salary: job.salary || null,
      posted_at: job.date ? new Date(job.date * 1000).toISOString() : null,
      language: 'en',
      skills: job.tags || []
    }
  });
}
return normalized;

// Normalize Remotive jobs
const raw = $input.first().json;
const jobs = raw.jobs || [];
const roleKeywords = ['devops', 'devsecops', 'backend', 'cloud', 'platform', 'infrastructure', 'sre', 'engineer', 'developer', 'fullstack'];

return jobs
  .filter(j => {
    const title = (j.job_title || j.title || '').toLowerCase();
    return roleKeywords.some(k => title.includes(k));
  })
  .map(j => ({
    json: {
      source: 'remotive',
      source_job_id: String(j.id),
      company: j.company_name || 'Unknown',
      title: j.job_title || j.title || '',
      location: j.candidate_required_location || 'Remote',
      remote: true,
      employment_type: (j.job_type || 'full-time').toLowerCase().replace('_', '-'),
      url: j.url || '',
      description: (j.description || '').replace(/<[^>]+>/g, ' ').substring(0, 6000),
      salary: j.salary || null,
      posted_at: j.publication_date ? new Date(j.publication_date).toISOString() : null,
      language: 'en',
      skills: j.tags || []
    }
  }));

// Normalize Arbeitnow jobs (EU-focused)
const raw = $input.first().json;
const jobs = raw.data || [];
const roleKeywords = ['devops', 'devsecops', 'backend', 'cloud', 'platform', 'infrastructure', 'sre', 'engineer', 'developer', 'fullstack', 'python', 'node', 'java'];

return jobs
  .filter(j => {
    const title = (j.title || '').toLowerCase();
    const desc = (j.description || '').toLowerCase();
    const isRelevant = roleKeywords.some(k => title.includes(k));
    const isEnglish = !desc.includes('sprichst du') && !desc.includes('vous parlez');
    return isRelevant && isEnglish;
  })
  .map(j => ({
    json: {
      source: 'arbeitnow',
      source_job_id: j.slug || String(j.id || ''),
      company: j.company_name || 'Unknown',
      title: j.title || '',
      location: j.location || 'Europe',
      remote: j.remote || false,
      employment_type: 'full-time',
      url: j.url || `https://www.arbeitnow.com/jobs/${j.slug}`,
      description: (j.description || '').replace(/<[^>]+>/g, ' ').substring(0, 6000),
      salary: null,
      posted_at: j.created_at ? new Date(j.created_at * 1000).toISOString() : null,
      language: 'en',
      skills: j.tags || []
    }
  }));

// Normalize WWR RSS feeds (both devops + backend)
const allItems = $input.all();
const normalized = [];

for (const item of allItems) {
  const xmlText = item.json.data || '';

  // Simple XML parsing for RSS
  const itemMatches = xmlText.matchAll(/<item>([\s\S]*?)<\/item>/g);

  for (const match of itemMatches) {
    const itemXml = match[1];

    const getField = (tag) => {
      const m = itemXml.match(new RegExp(`<${tag}[^>]*><!\\[CDATA\\[([\\s\\S]*?)\\]\\]><\/${tag}>|<${tag}[^>]*>([^<]*)<\/${tag}>`));
      return m ? (m[1] || m[2] || '').trim() : '';
    };

    const title = getField('title');
    const link = getField('link');
    const company = getField('region') || 'Unknown';
    const pubDate = getField('pubDate');
    const description = getField('description').replace(/<[^>]+>/g, ' ').substring(0, 6000);

    if (!title || !link) continue;

    // Extract company from title (format: "Company: Job Title")
    let companyName = 'Unknown';
    let jobTitle = title;
    if (title.includes(': ')) {
      const parts = title.split(': ');
      companyName = parts[0];
      jobTitle = parts.slice(1).join(': ');
    }

    normalized.push({
      json: {
        source: 'weworkremotely',
        source_job_id: link,
        company: companyName,
        title: jobTitle,
        location: 'Remote',
        remote: true,
        employment_type: 'full-time',
        url: link,
        description: description,
        salary: null,
        posted_at: pubDate ? new Date(pubDate).toISOString() : null,
        language: 'en',
        skills: []
      }
    });
  }
}

return normalized;

// Merge all normalized jobs from all sources
const allJobs = $input.all();
console.log(`Total normalized jobs: ${allJobs.length}`);
return allJobs;

// ── DETERMINISTIC PRE-FILTER ──────────────────────────────────
// Run before AI to save API quota

const EXCLUDED_ROLES = [
  'frontend developer', 'ui designer', 'ux designer', 'graphic designer',
  'product manager', 'data scientist', 'machine learning researcher',
  'ios developer', 'android developer', 'qa engineer', 'sales engineer',
  'account manager', 'scrum master', 'agile coach', 'project manager'
];

const REQUIRED_ROLE_KEYWORDS = [
  'devops', 'devsecops', 'backend', 'cloud', 'platform', 'infrastructure',
  'sre', 'site reliability', 'devops', 'ci/cd', 'cicd', 'pipeline',
  'software engineer', 'software developer', 'full stack', 'fullstack',
  'node', 'python', 'java', 'nestjs', 'docker', 'kubernetes', 'terraform',
  'aws', 'azure', 'gcp', 'engineer'
];

const SENIOR_ONLY_TERMS = ['10+ years', '8+ years', '7+ years', 'vp of', 'chief ', 'c-level', 'director of'];

const MANDATORY_NON_ENGLISH = ['sprichst du', 'nous cherchons', 'vous devez', 'hablas', 'parli italiano', 'vous parlez'];

const allJobs = $input.all();
const passed = [];
const rejected = [];

for (const item of allJobs) {
  const job = item.json;
  const title = (job.title || '').toLowerCase();
  const desc = (job.description || '').toLowerCase();
  const combined = `${title} ${desc}`;

  // 1. Check if role is explicitly excluded
  if (EXCLUDED_ROLES.some(r => title.includes(r))) {
    rejected.push({ ...job, filter_reason: 'Excluded role type' });
    continue;
  }

  // 2. Must have at least one relevant keyword
  const hasRelevantKeyword = REQUIRED_ROLE_KEYWORDS.some(k => title.includes(k) || desc.substring(0, 500).includes(k));
  if (!hasRelevantKeyword) {
    rejected.push({ ...job, filter_reason: 'No relevant role keywords found' });
    continue;
  }

  // 3. Reject if explicitly too senior
  if (SENIOR_ONLY_TERMS.some(t => combined.includes(t))) {
    rejected.push({ ...job, filter_reason: 'Requires too much experience' });
    continue;
  }

  // 4. Reject if mandatory non-English language
  if (MANDATORY_NON_ENGLISH.some(t => combined.includes(t))) {
    rejected.push({ ...job, filter_reason: 'Mandatory non-English language' });
    continue;
  }

  // 5. Must have valid URL
  if (!job.url || !job.url.startsWith('http')) {
    rejected.push({ ...job, filter_reason: 'Invalid or missing URL' });
    continue;
  }

  // Passed all filters!
  passed.push({ json: { ...job, filter_passed: true } });
}

console.log(`Pre-filter: ${passed.length} passed, ${rejected.length} rejected from ${allJobs.length} total`);
return passed;

// ── DEDUPLICATION ────────────────────────────────────────────
// Check which jobs are already in DB by collecting source+id pairs
// Return jobs that need to be inserted
const jobs = $input.all();
return jobs.map(j => ({
  json: {
    ...j.json,
    dedup_key: `${j.json.source}::${j.json.source_job_id || j.json.url}`
  }
}));

const results = $input.all();
const inserted = results.filter(r => r.json.id);
console.log(`Inserted ${inserted.length} new jobs`);
return [{ json: { jobs_inserted: inserted.length, total_processed: results.length } }];
